usage:
import { HeatWord } from "./HeatWord";
import "./HeatWord.css";

<HeatWord
  heat={60}
  soft={50}
  area={50}
  colors="Neon"
  shape="Dots"
/>

notes:
/* A FIELD, THEN A PALETTE. The word, blurred, is a grey field;
   the cursor adds heat to it; every pixel is looked up in a table
   from deep navy (the core) to a pink rim (the edge). Strokes that
   overlap in the field fuse, so the heat runs them together. */
g.shadowBlur = soft; g.fillText(word, x - off, y);   /* the blur */
g.globalCompositeOperation = "lighter";              /* the heat */
g.fillStyle = radial(cursor, white → clear);
for (px) out[px] = LUT[field[px]];                   /* the colour */
